DROP TRIGGER IF EXISTS marketing_notification_capture;
CREATE TRIGGER marketing_notification_capture
AFTER UPDATE OF data ON marketing_board
WHEN NEW.revision>OLD.revision AND NEW.data IS NOT OLD.data
BEGIN
 INSERT OR IGNORE INTO marketing_notification_changes(revision,task_id,old_task,next_task,created_at)
 SELECT NEW.revision,json_extract(next.value,'$.id'),CASE WHEN prior.key IS NULL THEN NULL ELSE json_object('artworkTaskType',json_extract(prior.value,'$.artworkTaskType'),'taskType',json_extract(prior.value,'$.taskType'),'taskSubtype',json_extract(prior.value,'$.taskSubtype'),'externalArtwork',json_extract(prior.value,'$.externalArtwork'),'id',json_extract(prior.value,'$.id'),'title',json_extract(prior.value,'$.title'),'status',json_extract(prior.value,'$.status'),'assignees',json(coalesce(json_extract(prior.value,'$.assignees'),'[]')),'tags',json(coalesce(json_extract(prior.value,'$.tags'),'[]')),'workflowResume',json_extract(prior.value,'$.workflowResume'),'approval',json(coalesce(json_extract(prior.value,'$.approval'),'null')),'purchase',json(CASE WHEN json_type(prior.value,'$.purchase')='object' THEN json_object('requiresArt',json(CASE WHEN json_extract(prior.value,'$.purchase.requiresArt')=0 THEN 'false' ELSE 'true' END),'stage',json_extract(prior.value,'$.purchase.stage')) ELSE 'null' END)) END,json_object('artworkTaskType',json_extract(next.value,'$.artworkTaskType'),'taskType',json_extract(next.value,'$.taskType'),'taskSubtype',json_extract(next.value,'$.taskSubtype'),'externalArtwork',json_extract(next.value,'$.externalArtwork'),'id',json_extract(next.value,'$.id'),'title',json_extract(next.value,'$.title'),'status',json_extract(next.value,'$.status'),'assignees',json(coalesce(json_extract(next.value,'$.assignees'),'[]')),'tags',json(coalesce(json_extract(next.value,'$.tags'),'[]')),'workflowResume',json_extract(next.value,'$.workflowResume'),'approval',json(coalesce(json_extract(next.value,'$.approval'),'null')),'purchase',json(CASE WHEN json_type(next.value,'$.purchase')='object' THEN json_object('requiresArt',json(CASE WHEN json_extract(next.value,'$.purchase.requiresArt')=0 THEN 'false' ELSE 'true' END),'stage',json_extract(next.value,'$.purchase.stage')) ELSE 'null' END)),strftime('%Y-%m-%dT%H:%M:%fZ','now')
 FROM json_each(NEW.data) next
 LEFT JOIN (WITH materialized_prior AS MATERIALIZED (SELECT key,value,json_extract(value,'$.id') AS task_id FROM json_each(OLD.data)) SELECT * FROM materialized_prior) prior ON prior.task_id=json_extract(next.value,'$.id')
 WHERE prior.key IS NULL OR json_object('artworkTaskType',json_extract(prior.value,'$.artworkTaskType'),'taskType',json_extract(prior.value,'$.taskType'),'taskSubtype',json_extract(prior.value,'$.taskSubtype'),'externalArtwork',json_extract(prior.value,'$.externalArtwork'),'id',json_extract(prior.value,'$.id'),'title',json_extract(prior.value,'$.title'),'status',json_extract(prior.value,'$.status'),'assignees',json(coalesce(json_extract(prior.value,'$.assignees'),'[]')),'tags',json(coalesce(json_extract(prior.value,'$.tags'),'[]')),'workflowResume',json_extract(prior.value,'$.workflowResume'),'approval',json(coalesce(json_extract(prior.value,'$.approval'),'null')),'purchase',json(CASE WHEN json_type(prior.value,'$.purchase')='object' THEN json_object('requiresArt',json(CASE WHEN json_extract(prior.value,'$.purchase.requiresArt')=0 THEN 'false' ELSE 'true' END),'stage',json_extract(prior.value,'$.purchase.stage')) ELSE 'null' END)) IS NOT json_object('artworkTaskType',json_extract(next.value,'$.artworkTaskType'),'taskType',json_extract(next.value,'$.taskType'),'taskSubtype',json_extract(next.value,'$.taskSubtype'),'externalArtwork',json_extract(next.value,'$.externalArtwork'),'id',json_extract(next.value,'$.id'),'title',json_extract(next.value,'$.title'),'status',json_extract(next.value,'$.status'),'assignees',json(coalesce(json_extract(next.value,'$.assignees'),'[]')),'tags',json(coalesce(json_extract(next.value,'$.tags'),'[]')),'workflowResume',json_extract(next.value,'$.workflowResume'),'approval',json(coalesce(json_extract(next.value,'$.approval'),'null')),'purchase',json(CASE WHEN json_type(next.value,'$.purchase')='object' THEN json_object('requiresArt',json(CASE WHEN json_extract(next.value,'$.purchase.requiresArt')=0 THEN 'false' ELSE 'true' END),'stage',json_extract(next.value,'$.purchase.stage')) ELSE 'null' END));
END;
